insert into public.articles (id,title,dek,cat,chan,syms,free,mins,img,body,secs,notes,meta,status,published_at) values ('gamma-earnings','财报周前的 Gamma 地形：做市商对冲会放大还是压住波动？','正 Gamma 区间里，价格往往被“钉”在大额行权价附近；一旦跌破翻转点，对冲方向就会反过来。','期权与波动率','期权',array['SPX','QQQ']::text[],false,6,'trader','["每到财报密集周，期权市场的仓位结构都会变得格外重要。原因很简单：大量期权集中在少数几个行权价上，做市商为了保持中性，必须跟着价格买卖标的，这些对冲交易本身就会反过来影响价格。","当做市商整体持有正 Gamma 时，价格上涨他们卖出、价格下跌他们买入，相当于在市场里放了一个“减震器”。这就是为什么在某些交易日，指数会反复围绕一个大额行权价来回震荡，怎么也走不远。",{"t":"chart","sym":"SPX"},"问题出在翻转点以下。一旦价格跌入负 Gamma 区，同样的对冲逻辑会变成“追涨杀跌”：价格下跌，做市商需要继续卖出，波动被放大而不是被吸收。",{"t":"quote","text":"翻转点不是支撑位，它是市场“性格”切换的地方。"},"对于做卖方策略的交易者，这意味着同一个铁蝶，在翻转点上方和下方的风险完全不同。我们在每日盘前会更新三个关键价位，并标注当天的结构偏向。",{"t":"levels","sym":"SPX"},"本周还需要留意两类事件：一是成分股龙头的财报，它们的隐含波动率在财报前后的变化会通过指数期权传导；二是周五的到期结构，大量周度合约到期后，Gamma 的“钉住”效应会明显减弱。"]'::jsonb,'[[1,"一、正 Gamma：市场里的“减震器”"],[3,"二、翻转点之下：对冲方向反转"],[7,"三、本周要留意的两类事件"]]'::jsonb,'[[1,"Gamma 敞口按“标的变动 1% 时做市商需要对冲的美元金额”计算，假设做市商持有看涨期权空头、看跌期权多头，详见“数据与方法论”。"],[3,"翻转点为全部到期日加总后的净 Gamma 由负转正的价格，盘中会随标的价格与隐含波动率变化。"],[7,"成分股财报对指数隐含波动率的传导，取决于该成分股在指数中的权重与财报日隐含波动率的跳升幅度。"]]'::jsonb,'{"events":["财报季","OPEX"],"topics":["Gamma 结构","波动率"]}'::jsonb,'published','2026-10-21T20:44:03.748Z') on conflict (id) do nothing;
insert into public.articles (id,title,dek,cat,chan,syms,free,mins,img,body,secs,notes,meta,status,published_at) values ('term-structure','波动率期限结构重新变陡，卖方策略该如何调整','近月隐含波动率回落快于远月，期限结构的斜率回到今年中位数上方。','期权与波动率','期权',array['VIX','SPX']::text[],false,5,'analyst','["VIX 期货曲线在过去一周重新变陡：近月合约回落，远月相对坚挺。这种形态通常出现在短期事件风险释放、但中期不确定性仍在的阶段。","对卖方策略而言，陡峭的期限结构意味着卖出近月、买入远月的日历价差有更好的赔率，但也要注意近月波动率已处于偏低位置，继续下行的空间有限。",{"t":"quote","text":"期限结构变陡，说的不是市场更安全，而是风险被推到了后面。"},"我们的观察是：在翻转点上方，近月卖方仍然占优；一旦指数跌破翻转点，近月隐含波动率可能快速抬升，日历价差的近腿会承受压力。","建议关注每日盘前更新的 VIX 期限结构快照，以及 SPX 翻转点的位置变化。"]'::jsonb,'[[1,"一、卖方的赔率在哪里"],[3,"二、翻转点上下的两种结论"]]'::jsonb,'[[0,"期限结构斜率以 VIX 期货第二个月合约减第一个月合约计算。"],[1,"日历价差在近月隐含波动率处于一年 25% 分位以下时，期权费收入偏低，风险收益比下降。"]]'::jsonb,'{"events":["OPEX"],"topics":["波动率","期限结构"]}'::jsonb,'published','2026-10-21T15:44:03.748Z') on conflict (id) do nothing;
insert into public.articles (id,title,dek,cat,chan,syms,free,mins,img,body,secs,notes,meta,status,published_at) values ('treasury-auction','美债拍卖需求转弱，期限溢价重回交易台讨论中心','长端拍卖的投标倍数下滑，尾部利差扩大，利率波动率开始向股票波动率传导。','宏观','宏观',array['US10Y']::text[],false,9,'fed','["最近几次长端国债拍卖的需求指标走弱：投标倍数低于近期均值，海外买家占比下降，拍卖尾部利差扩大。这些信号让“期限溢价”重新成为交易台的热门话题。","期限溢价上升，意味着投资者持有长债要求更高的补偿。它对股票的影响主要通过两条路径：一是折现率抬升压制估值，二是利率波动率上升带动股票隐含波动率。",{"t":"quote","text":"利率波动率是股票波动率的上游。"},"从历史上看，MOVE 指数与 VIX 的相关性在利率主导的阶段明显增强。当前两者的价差处于偏高位置，若利率波动率继续抬升，股票期权的卖方需要更谨慎。","后续关注：本周的 7 年期拍卖、官员讲话中对资产负债表的表述，以及财政部再融资公告。"]'::jsonb,'[[1,"一、期限溢价如何传导到股票"],[3,"二、利率波动率与 VIX"]]'::jsonb,'[[0,"尾部利差（tail）指中标收益率高于发行前交易水平（when-issued）的幅度，正值代表需求偏弱。"],[3,"MOVE 指数衡量美债期权隐含波动率，可视为“债券市场的 VIX”。"]]'::jsonb,'{"events":["国债拍卖","FOMC"],"topics":["利率","期限溢价"]}'::jsonb,'published','2026-10-21T10:44:03.748Z') on conflict (id) do nothing;
insert into public.articles (id,title,dek,cat,chan,syms,free,mins,img,body,secs,notes,meta,status,published_at) values ('shutdown-risk','预算谈判进入倒计时：停摆风险如何传导到利率和波动率','政治事件的市场影响，往往先体现在短端利率和事件日附近的期权定价上。','美国政治','美国政治',array['SPX','US10Y']::text[],false,7,'capitol','["预算谈判进入关键阶段。对市场而言，真正需要跟踪的不是政治表态本身，而是时间表：哪一天是期限、哪些数据发布可能因停摆延迟。","历史上的政府停摆对股指的直接影响通常有限，但会通过两条路径影响波动率：一是经济数据延迟发布，让市场在“没有数据”的状态下交易；二是短端国债的定价扭曲。",{"t":"quote","text":"政策日历有时比财报更容易触发 Gamma 翻转。"},"期权市场上，事件日附近的到期合约隐含波动率已出现小幅抬升。若谈判进展不顺，指数可能在流动性较弱的时段跌破翻转点，进入放大波动的区间。","我们会在每日政策追踪快照中更新国会日程与市场相关节点。本文不对任何政治立场作出评价。"]'::jsonb,'[[1,"一、真正的传导路径"],[3,"二、期权市场已经开始定价"]]'::jsonb,'[[1,"2018—2019 年停摆期间，部分经济数据推迟发布超过一个月。"]]'::jsonb,'{"events":["预算谈判","FOMC"],"topics":["政策","利率","波动率"]}'::jsonb,'published','2026-10-21T05:44:03.748Z') on conflict (id) do nothing;
insert into public.articles (id,title,dek,cat,chan,syms,free,mins,img,body,secs,notes,meta,status,published_at) values ('oil-gold','原油与黄金走势分化：美元走弱下的大宗配置','油价跟随需求预期回落，金价在美元走弱与避险需求之间维持高位。','大宗商品','大宗商品',array['WTI','GOLD']::text[],false,5,'oil','["过去两周，原油与黄金走出明显分化：WTI 跟随需求预期下修回落，黄金则在美元走弱和央行购金的支撑下维持高位震荡。","原油方面，库存数据连续两周超预期累库，炼厂开工率季节性回落；期权市场上，看跌偏度有所抬升。",{"t":"quote","text":"当美元走弱时，黄金看的是信用，原油看的是需求。"},"黄金方面，隐含波动率回落到近三个月低位，期权市场对继续上行的定价相对克制。","后续关注：EIA 周度库存、OPEC+ 会议纪要以及美元指数的走势。"]'::jsonb,'[[1,"一、原油：库存与偏度"],[3,"二、黄金：波动率回落"]]'::jsonb,'[[1,"看跌偏度为 25 Delta 看跌期权与看涨期权的隐含波动率差。"]]'::jsonb,'{"events":["EIA 库存","OPEC+"],"topics":["大宗商品","美元"]}'::jsonb,'published','2026-10-21T00:44:03.748Z') on conflict (id) do nothing;
insert into public.articles (id,title,dek,cat,chan,syms,free,mins,img,body,secs,notes,meta,status,published_at) values ('breadth','科技股领涨背后：等权与市值加权的广度分化','市值加权指数创新高，等权指数却跑输，上涨集中在少数龙头。','美股','美股',array['SPX','QQQ','NVDA','AAPL']::text[],true,4,'skyline','["今天开盘后科技股领涨，标普 500 市值加权指数走强，但等权指数表现落后。这种分化说明上涨集中在少数大市值公司。","市场广度偏弱并不必然意味着顶部，但它会让指数对少数个股的财报更加敏感。龙头公司的期权仓位，也会通过指数期权影响做市商的整体对冲需求。",{"t":"quote","text":"广度是指数的体检报告。"},"我们建议同时关注等权指数与市值加权指数的相对表现，以及龙头个股的财报日程。本文为免费阅读文章。"]'::jsonb,'[[1,"一、广度为什么重要"]]'::jsonb,'[[0,"等权标普 500 指数中，每只成分股权重相同，不受市值大小影响。"]]'::jsonb,'{"events":["财报季"],"topics":["市场广度","美股结构"]}'::jsonb,'published','2026-10-20T19:44:03.748Z') on conflict (id) do nothing;
insert into public.articles (id,title,dek,cat,chan,syms,free,mins,img,body,secs,notes,meta,status,published_at) values ('zdte-share','0DTE 占比突破六成：当日到期期权如何改变日内波动','当日到期合约已成为 SPX 期权成交的主体，日内的 Gamma 分布每小时都在变化。','期权与波动率','期权',array['SPX']::text[],false,7,'trader2','["过去两年，SPX 当日到期期权的成交占比从三成升至六成以上。成交结构的变化，让日内波动越来越受到短期仓位的影响。","与月度合约不同，当日到期合约的 Gamma 极高，而且集中在平值附近。做市商对这些合约的对冲，会在午后明显加速。",{"t":"chart","sym":"SPX"},"我们观察到，上午的价格区间往往由隔夜仓位决定，而午后则更多受到当日新开仓位的影响。正 Gamma 主导时，尾盘容易回到大额行权价；负 Gamma 主导时，尾盘波动明显放大。",{"t":"quote","text":"0DTE 不是噪音，它是日内结构本身。"},"对日内交易者而言，午后一小时的结构判断比开盘时更重要。我们会在盘中快照里标注当日到期合约的集中行权价。"]'::jsonb,'[[1,"一、成交结构的变化"],[3,"二、日内 Gamma 的“潮汐”"],[5,"三、对交易者意味着什么"]]'::jsonb,'[]'::jsonb,'{"events":["OPEX"],"topics":["0DTE","Gamma 结构"]}'::jsonb,'published','2026-10-20T14:44:03.748Z') on conflict (id) do nothing;
insert into public.articles (id,title,dek,cat,chan,syms,free,mins,img,body,secs,notes,meta,status,published_at) values ('skew-premium','偏斜处于高位：尾部保护为什么越来越贵','虚值看跌期权的隐含波动率与平值之差，已回到过去三年的高分位。','期权与波动率','期权',array['VIX','SPX']::text[],false,6,'analyst2','["指数上涨的同时，虚值看跌期权却越来越贵。这种背离并不常见，它说明机构在上涨行情里仍然愿意为尾部风险付费。","需求主要来自两类资金：一是在高位锁定收益的养老金与保险资金，二是对冲集中持仓的量化策略。",{"t":"spark","sym":"VIX","cap":"VIX 指数近 30 个交易日走势"},"偏斜高企时，卖出看跌价差的赔率看起来更好，但尾部风险也被市场定价得更充分。历史上，偏斜处于高分位并不能单独预示下跌。","我们更关注偏斜与 VIX 期限结构的组合：若前端同时转为贴水，才更可能对应真正的压力事件。"]'::jsonb,'[[1,"一、谁在买保护"],[3,"二、偏斜与现货的背离"]]'::jsonb,'[]'::jsonb,'{"events":[],"topics":["波动率","偏斜"]}'::jsonb,'published','2026-10-20T09:44:03.748Z') on conflict (id) do nothing;
insert into public.articles (id,title,dek,cat,chan,syms,free,mins,img,body,secs,notes,meta,status,published_at) values ('curve-steepener','曲线陡峭化交易回归：2 年与 10 年利差转正之后','短端随降息预期回落，长端被期限溢价托住，曲线形态正在改变股票的估值锚。','债券','债券',array['US2Y','US10Y']::text[],false,8,'bond','["2 年期与 10 年期国债利差转正后，市场对“陡峭化”交易的兴趣明显回升。短端收益率跟随降息预期下行，长端则因为财政供给和期限溢价维持高位。","这种形态通常出现在宽松周期的初段。它对银行股相对有利，对高估值成长股则意味着折现率并没有随降息同步下降。",{"t":"curve","cap":"美国国债收益率曲线：今日与一周前"},"对于股票投资者，关键在长端。10 年期收益率若继续停留在 4% 以上，指数估值的扩张空间有限，市场的上涨将更依赖盈利。","我们将在每周的债券快照中跟踪 2s10s 与 5s30s 两组利差，并标注国债拍卖结果对长端的影响。"]'::jsonb,'[[1,"一、短端与长端的分歧"],[3,"二、对股票估值的影响"]]'::jsonb,'[]'::jsonb,'{"events":["国债拍卖","FOMC"],"topics":["利率","收益率曲线"]}'::jsonb,'published','2026-10-20T04:44:03.748Z') on conflict (id) do nothing;
insert into public.articles (id,title,dek,cat,chan,syms,free,mins,img,body,secs,notes,meta,status,published_at) values ('futures-basis','股指期货基差与季度换月：资金成本告诉了我们什么','12 月合约的隐含融资利率高于无风险利率，杠杆多头的需求仍然旺盛。','期货','期货',array['ES','NQ']::text[],false,5,'pit','["股指期货相对现货的升水，本质上是持有现货的融资成本减去股息。当隐含融资利率明显高于无风险利率时，说明市场愿意为杠杆多头支付溢价。","本季度 ES 12 月合约的隐含融资利率高出 SOFR 约 40 个基点，处于近两年的较高水平。",{"t":"spark","sym":"ES","cap":"标普 500 期货（ES）近 30 个交易日走势"},"换月窗口前后，基差往往出现短暂扩大，流动性从近月向远月迁移。对冲基金的展期需求，会在这一周集中体现在成交量上。","基差持续偏高时，期货端的多头仓位更为拥挤。若出现快速去杠杆，期货往往领先现货下跌。"]'::jsonb,'[[1,"一、基差里的融资成本"],[3,"二、换月前后的流动性"]]'::jsonb,'[]'::jsonb,'{"events":["季度换月"],"topics":["基差","流动性"]}'::jsonb,'published','2026-10-19T23:44:03.748Z') on conflict (id) do nothing;
insert into public.articles (id,title,dek,cat,chan,syms,free,mins,img,body,secs,notes,meta,status,published_at) values ('mega-cap-week','科技巨头财报周：占指数三成权重的集中风险','MSFT、Alphabet、Meta、AAPL 与AMZN 将在同一周发布财报，指数对单一公司的敏感度达到新高。','美股','美股',array['NVDA','AAPL','SPX']::text[],false,6,'chip','["五家科技巨头将在下周集中发布财报，它们合计占标普 500 约三成权重。指数的走势，在很大程度上取决于这几个晚上。","权重集中意味着指数层面的分散效果下降。单一公司财报后的大幅波动，会直接传导到 SPX 期权的对冲需求。",{"t":"chart","sym":"QQQ"},"从期权定价看，五家公司财报次日的隐含波动合计高于过去八个季度的平均水平，市场对 AI 资本开支的回报周期仍有分歧。","我们为每家公司准备了财报数据解析，包括历史表现、期权定价与情景分析，订阅用户可在财报栏中查阅。"]'::jsonb,'[[1,"一、权重集中的代价"],[3,"二、期权市场如何定价"]]'::jsonb,'[]'::jsonb,'{"events":["财报季"],"topics":["指数权重","波动率"]}'::jsonb,'published','2026-10-19T18:44:03.748Z') on conflict (id) do nothing;
insert into public.articles (id,title,dek,cat,chan,syms,free,mins,img,body,secs,notes,meta,status,published_at) values ('cpi-preview','9 月 CPI 前瞻：核心服务通胀与期权的事件溢价','SPX 期权为 CPI 当日定价约 ±1.1% 的波动，高于过去一年的实际平均。','宏观','宏观',array['US10Y','SPX']::text[],false,7,'shop','["市场预期 9 月核心 CPI 同比 3.1%。在商品通胀已经回落的情况下，住房以外的核心服务通胀决定了美联储的节奏。","若核心服务环比再次高于 0.4%，市场对 12 月降息的预期将明显回落，短端收益率上行。",{"t":"spark","sym":"US10Y","cap":"10 年期美债收益率近 30 个交易日走势"},"SPX 期权为数据公布当日定价约 ±1.1% 的波动，高于过去 12 次 CPI 的实际平均 ±0.8%。事件溢价偏高时，数据落地后隐含波动通常快速回落。","对于持有期权多头的交易者，数据公布前的时间价值损耗值得重视；卖方则需要警惕结果大幅偏离预期的尾部情形。"]'::jsonb,'[[1,"一、核心服务是关键"],[3,"二、事件溢价是否过高"]]'::jsonb,'[]'::jsonb,'{"events":["CPI"],"topics":["通胀","事件溢价"]}'::jsonb,'published','2026-10-19T13:44:03.748Z') on conflict (id) do nothing;
insert into public.articles (id,title,dek,cat,chan,syms,free,mins,img,body,secs,notes,meta,status,published_at) values ('copper-dollar','铜价与美元：需求预期还是供给扰动','铜价在美元走强的背景下仍然上涨，供给端的扰动正在压过需求预期。','大宗商品','大宗商品',array['HG','GOLD']::text[],false,5,'copper','["通常情况下，美元走强会压制以美元计价的大宗商品。但过去一个月，铜价在美元指数上涨的同时仍然走高。","主要原因在供给端：南美主要矿山的产量指引下调，冶炼加工费降至历史低位。",{"t":"spark","sym":"HG","cap":"COMEX 铜期货近 30 个交易日走势"},"交易所库存持续下降，期限结构的近月升水扩大，说明现货端偏紧。这种结构下，价格回调往往较浅。","需求端仍是不确定因素。若主要经济体的制造业数据继续疲弱，供给扰动带来的溢价可能难以持续。"]'::jsonb,'[[1,"一、背离从何而来"],[3,"二、库存与期限结构"]]'::jsonb,'[]'::jsonb,'{"events":[],"topics":["大宗商品","美元"]}'::jsonb,'published','2026-10-19T08:44:03.748Z') on conflict (id) do nothing;
insert into public.articles (id,title,dek,cat,chan,syms,free,mins,img,body,secs,notes,meta,status,published_at) values ('midterm-vol','中期选举前的波动率定价：历史规律与今年的不同','VIX 期货 11 月合约相对 10 月的升水，反映了市场对选举结果的不确定性。','美国政治','美国政治',array['SPX','VIX']::text[],false,6,'capitol','["从历史数据看，中期选举前一个月的指数波动通常高于全年平均，而选举后两个月的表现则相对较强。","这一规律的核心在于不确定性的消除：结果落地后，无论哪一方胜出，政策预期都会变得更加清晰。",{"t":"vx","cap":"VIX 期货期限结构"},"今年 VIX 期货 11 月合约相对 10 月的升水明显扩大，说明市场已为选举周的波动支付溢价。","我们将在选举周发布专题快照，跟踪关键州的结果与期权市场的实时反应。所有政治类内容均经过人工审核。"]'::jsonb,'[[1,"一、历史上的选举前波动"],[3,"二、今年的期权市场"]]'::jsonb,'[]'::jsonb,'{"events":["选举"],"topics":["政策","波动率"]}'::jsonb,'published','2026-10-19T03:44:03.748Z') on conflict (id) do nothing;
insert into public.datasets (kind,payload,source) values ('earn','{"NFLX":{"name":"NFLX","en":"Netflix","q":"2026 年三季度","eps":6.98,"rev":"115.1 亿美元","revY":"+16%","imp":7.4,"avg":6.8,"beat":"7/8","w":0.5,"iv":58,"ivr":82,"pc":0.74,"watch":[["付费会员净增","市场预期约 410 万"],["广告层收入","管理层目标全年翻倍"],["营业利润率","公司指引 29%"]],"view":"定价能力与广告层是本季的两条主线。提价后的流失率若维持在低位，全年利润率指引存在上调空间；反之，会员净增低于 300 万会让市场重新审视估值。"},"TSLA":{"name":"TSLA","en":"Tesla","q":"2026 年三季度","eps":0.54,"rev":"262 亿美元","revY":"+3%","imp":8.9,"avg":9.6,"beat":"4/8","w":2.1,"iv":71,"ivr":64,"pc":0.88,"watch":[["汽车毛利率（不含积分）","市场预期约 17.0%"],["储能装机","上季 9.6 GWh"],["自动驾驶与机器人进展","电话会表述决定次日方向"]],"view":"交付数据已提前公布，本季看点在毛利率和电话会。期权隐含波动低于历史平均，若管理层给出明确的新车型或自动驾驶时间表，实际波动可能超出期权定价。"},"IBM":{"name":"IBM","en":"IBM","q":"2026 年三季度","eps":2.45,"rev":"163 亿美元","revY":"+4%","imp":5.2,"avg":4.9,"beat":"8/8","w":0.4,"iv":33,"ivr":55,"pc":0.69,"watch":[["软件业务增速","市场预期约 9%"],["红帽增速","上季 12%"],["生成式 AI 订单","累计签约金额"]],"view":"连续八个季度超出盈利预期，市场对“超预期”本身已不敏感，次日走势更取决于软件增速和全年自由现金流指引。"},"INTC":{"name":"INTC","en":"Intel","q":"2026 年三季度","eps":0.02,"rev":"136 亿美元","revY":"+3%","imp":9.8,"avg":8.7,"beat":"5/8","w":0.2,"iv":76,"ivr":71,"pc":0.81,"watch":[["代工业务亏损","上季营业亏损 31 亿美元"],["毛利率指引","市场预期约 38%"],["18A 制程良率","电话会表述"]],"view":"盈利接近盈亏平衡，任何指引变化都会被放大。期权定价的波动高于历史均值，说明市场对代工进展的分歧仍然很大。"},"MSFT":{"name":"MSFT","en":"Microsoft","q":"2027 财年一季度","eps":3.65,"rev":"754 亿美元","revY":"+14%","imp":4.6,"avg":4.1,"beat":"8/8","w":6.6,"iv":29,"ivr":58,"pc":0.62,"watch":[["Azure 增速","市场预期约 37%"],["资本开支","上季 242 亿美元"],["Copilot 付费席位","管理层披露口径"]],"view":"Azure 增速仍是唯一能明显改变股价方向的数字。MSFT 占 SPX 权重较高，财报后的走势会直接影响指数期权的对冲需求，尤其是在同日 FOMC 决议之后。"},"GOOGL":{"name":"GOOGL","en":"Alphabet","q":"2026 年三季度","eps":2.28,"rev":"993 亿美元","revY":"+13%","imp":5.9,"avg":5.6,"beat":"7/8","w":4,"iv":34,"ivr":61,"pc":0.66,"watch":[["搜索收入增速","市场预期约 11%"],["云业务利润率","上季 20.7%"],["资本开支指引","全年口径"]],"view":"搜索业务在 AI 竞争下的韧性是核心问题。云业务利润率连续改善，若资本开支指引再次上调，市场关注点会转向回报周期。"},"META":{"name":"META","en":"Meta","q":"2026 年三季度","eps":6.7,"rev":"498 亿美元","revY":"+20%","imp":7.8,"avg":9.1,"beat":"7/8","w":2.8,"iv":41,"ivr":66,"pc":0.71,"watch":[["广告展示量与单价","两者增速拆分"],["资本开支指引","2027 年初步口径"],["Reality Labs 亏损","上季 45 亿美元"]],"view":"历史上 Meta 财报后的实际波动经常超过期权定价，本季隐含波动再次低于历史均值。资本开支指引是最可能引发大幅波动的变量。"},"AAPL":{"name":"AAPL","en":"Apple","q":"2026 财年四季度","eps":1.76,"rev":"1015 亿美元","revY":"+7%","imp":4.1,"avg":3.6,"beat":"8/8","w":6.9,"iv":26,"ivr":49,"pc":0.67,"watch":[["iPhone 收入","新机首个完整季度"],["服务业务毛利率","上季 75.6%"],["大中华区收入","同比变化"]],"view":"新机周期的首个季度通常给出保守指引。AAPL 权重最高，若与AMZN 同晚发布，盘后指数期货的波动将同时反映两家公司的结果。"},"AMZN":{"name":"AMZN","en":"Amazon","q":"2026 年三季度","eps":1.58,"rev":"1778 亿美元","revY":"+10%","imp":6.6,"avg":7.2,"beat":"6/8","w":3.9,"iv":37,"ivr":60,"pc":0.7,"watch":[["AWS 增速","市场预期约 19%"],["北美零售利润率","上季 6.5%"],["四季度营业利润指引","节日季口径"]],"view":"AWS 增速是否重新加速决定市场情绪。四季度指引历来偏保守，次日走势往往先反映 AWS，再在电话会后修正。"},"NVDA":{"name":"NVDA","en":"NVIDIA","q":"2027 财年三季度","eps":1.12,"rev":"548 亿美元","revY":"+56%","imp":7.1,"avg":6.4,"beat":"8/8","w":7.4,"iv":52,"ivr":68,"pc":0.79,"watch":[["数据中心收入","市场预期约 488 亿美元"],["毛利率","公司指引 73.5%"],["下季收入指引","与市场预期的差距"]],"view":"NVDA 是对指数期权影响最大的单一财报。超预期已是常态，市场真正交易的是下季指引相对预期的幅度。"}}'::jsonb,'sample') on conflict (kind) do update set payload=excluded.payload, source=excluded.source, updated_at=now();
