",22],["NVDA","NVIDIA",2.8,5.7,"增持",15.1],["IEMG","iShares Core MSCI EM",2.6,5.3,"新建",null],["GLD","SPDR Gold Shares",2.2,4.5,"增持",9.6],["PG","Procter & Gamble",1.9,3.9,"不变",0],["JNJ","Johnson & Johnson",1.7,3.5,"增持",4],["META","Meta",1.5,3.1,"减持",-7.2],["WMT","Walmart",1.4,2.9,"不变",0]]},{"id":"pershing","name":"Pershing Square","fund":"13F 申报","src":"2026 年二季度","asof":"08/14","aum":"131 亿美元","n":9,"rows":[["UBER","Uber",19.8,26,"增持",4.4],["BN","Brookfield",17.5,22.9,"不变",0],["GOOGL","Alphabet",13.9,18.2,"减持",-3],["HLT","Hilton",12.6,16.5,"不变",0],["QSR","Restaurant Brands",11,14.4,"不变",0],["AMZN","Amazon",9.7,12.7,"新建",null],["CMG","Chipotle",8.4,11,"减持",-15.8],["HHH","Howard Hughes",7.1,9.3,"增持",2.5]]}]'::jsonb,'sample') on conflict (kind) do update set payload=excluded.payload, source=excluded.source, updated_at=now();
insert into public.datasets (kind,payload,source) values ('congress','[["10/20","10/02","众议员 A","众议院","CA","民主党","NVDA","买入","$250,001–$500,000","配偶"],["10/19","09/26","参议员 B","参议院","TX","共和党","XOM","卖出","$15,001–$50,000","本人"],["10/18","09/30","众议员 C","众议院","FL","共和党","PLTR","买入","$50,001–$100,000","本人"],["10/17","09/12","众议员 A","众议院","CA","民主党","AAPL","卖出（部分）","$100,001–$250,000","配偶"],["10/16","10/01","参议员 D","参议院","GA","民主党","MSFT","买入","$1,001–$15,000","本人"],["10/15","09/18","众议员 E","众议院","NY","民主党","TSLA","买入（看涨期权）","$15,001–$50,000","本人"],["10/14","09/22","众议员 F","众议院","OH","共和党","LMT","买入","$15,001–$50,000","配偶"],["10/11","08/29","参议员 G","参议院","PA","共和党","JPM","卖出","$50,001–$100,000","本人"],["10/10","09/25","众议员 C","众议院","FL","共和党","AVGO","买入","$15,001–$50,000","本人"],["10/09","09/08","众议员 H","众议院","IL","民主党","GOOGL","卖出","$1,001–$15,000","子女"],["10/08","09/19","参议员 B","参议院","TX","共和党","CVX","卖出","$15,001–$50,000","本人"],["10/07","09/15","众议员 E","众议院","NY","民主党","NVDA","买入","$50,001–$100,000","本人"]]'::jsonb,'sample') on conflict (kind) do update set payload=excluded.payload, source=excluded.source, updated_at=now();
